private void executeCommand(String cmd, Scanner sc) {
        switch (cmd) {
            case "ADD":
                if (sc.hasNext()) {
                    roster.add(sc.next());
                }
                break;

            case "REMOVE":
                if (sc.hasNext()) {
                    // BUG: Treats name parameter as an integer index!
                    int index = sc.nextInt(); 
                    roster.remove(index);
                }
                break;

            case "STATUS":
                printStatus();
                break;
        }
    }
}

